import { FC, HTMLAttributes, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Calendar, Flex, Radio, Select, Tabs, TabsProps, Timeline } from 'antd';
import dayjs from 'dayjs';

import { EFilters, OPTIONS_MAX_HEIGHT_NOTIFICATIONS, PlannerFilters, useFilters } from 'features/Filters';
import { Content, Page, PageTitle } from 'shared/ui';

import 'dayjs/locale/ru';

import styles from './Planner.module.scss';
dayjs.locale('ru');

interface IPlannerProps extends HTMLAttributes<HTMLDivElement> {}

export const Planner: FC<IPlannerProps> = () => {
	const { t } = useTranslation();
	const { getFilterValue, onFilterChange } = useFilters();

	const items: TabsProps['items'] = [
		{
			key: '1',
			label: t('Календарь'),
			//children: 'Content of Tab Pane 1',
		},
		{
			key: '2',
			label: t('История постов'),
			//children: 'Content of Tab Pane 2',
		},
	];

	const [type, setType] = useState<'day' | 'week' | 'month' | 'year'>('year');

	const month = getFilterValue(EFilters.PLANNER_MONTH) || new Date().toLocaleDateString('ru-RU', { month: '2-digit' });
	const year = getFilterValue(EFilters.PLANNER_YEAR) || new Date().getFullYear().toString();
	const date = `${year}-${month}-01`;
	console.log(dayjs(date).format('MMMM'));

	return (
		<Page className={styles.page}>
			<PageTitle subtitle={t('Выберите время или период, когда хотите видеть публикации в своём канале')}>
				{t('Планировщик постов')}
			</PageTitle>

			<div className={styles.tabsWrapper}>
				<Tabs defaultActiveKey="1" items={items} tabBarGutter={0} centered />
			</div>

			<Content>
				<Flex vertical gap={16}>
					<Flex vertical gap={8}>
						<PlannerFilters />

						<Radio.Group value={type} onChange={(e) => setType(e.target.value)} block size="large">
							<Radio.Button value="day">{t('День')}</Radio.Button>
							<Radio.Button value="week">{t('Неделя')}</Radio.Button>
							<Radio.Button value="month">{t('Месяц')}</Radio.Button>
							<Radio.Button value="year">{t('Год')}</Radio.Button>
						</Radio.Group>

						<Flex gap={8}>
							<Select
								value={month}
								options={[
									{ label: t('Январь'), value: '01' },
									{ label: t('Февраль'), value: '02' },
									{ label: t('Март'), value: '03' },
									{ label: t('Апрель'), value: '04' },
									{ label: t('Май'), value: '05' },
									{ label: t('Июнь'), value: '06' },
									{ label: t('Июль'), value: '07' },
									{ label: t('Август'), value: '08' },
									{ label: t('Сентябрь'), value: '09' },
									{ label: t('Октябрь'), value: '10' },
									{ label: t('Ноябрь'), value: '11' },
									{ label: t('Декабрь'), value: '12' },
								]}
								onChange={(value) => onFilterChange(EFilters.PLANNER_MONTH, value)}
								placeholder={t('Выберите месяц')}
								size="large"
								showSearch
								listHeight={OPTIONS_MAX_HEIGHT_NOTIFICATIONS}
								style={{ width: '100%' }}
							/>

							<Select
								value={year}
								options={[
									{ label: '2024', value: '2024' },
									{ label: '2025', value: '2025' },
								]}
								onChange={(value) => onFilterChange(EFilters.PLANNER_YEAR, value)}
								placeholder={t('Выберите год')}
								size="large"
								showSearch
								listHeight={OPTIONS_MAX_HEIGHT_NOTIFICATIONS}
								style={{ width: 110 }}
							/>
						</Flex>
					</Flex>

					{type === 'day' && (
						<div className={styles.timelineWrapper}>
							<Timeline
								mode={'left'}
								items={[
									{
										label: '13:00',
										children: (
											<img
												style={{ height: 80 }}
												src="https://api.dicebear.com/7.x/adventurer-neutral/svg?seed=mail@ashallendesign.co.uk"
											/>
										),
									},
									{
										label: '14:00',
										children: (
											<Flex vertical align="start" gap={8}>
												<img
													style={{ height: 80 }}
													src="https://api.dicebear.com/7.x/adventurer-neutral/svg?seed=mail@ashallendesign.co.uk"
												/>
												<img
													style={{ height: 80 }}
													src="https://api.dicebear.com/7.x/adventurer-neutral/svg?seed=mail@ashallendesign.co.uk"
												/>
											</Flex>
										),
									},
									{
										label: '16:00',
										children: (
											<img
												style={{ height: 80 }}
												src="https://api.dicebear.com/7.x/adventurer-neutral/svg?seed=mail@ashallendesign.co.uk"
											/>
										),
									},
									{
										label: '19:00',
										children: (
											<img
												style={{ height: 80 }}
												src="https://api.dicebear.com/7.x/adventurer-neutral/svg?seed=mail@ashallendesign.co.uk"
											/>
										),
									},
								]}
							/>
						</div>
					)}

					{type === 'month' && (
						<div className={styles.calendarWrapper}>
							<Calendar
								style={{ minWidth: 600 }}
								value={dayjs(date)}
								cellRender={(a) => {
									return (
										(a.date() === 10 || a.date() === 20) && (
											<Flex>
												<img
													className={styles.monthCalendarCellIcon}
													src="https://api.dicebear.com/7.x/adventurer-neutral/svg?seed=mail@ashallendesign.co.uk"
												/>
												<img
													className={styles.monthCalendarCellIcon}
													src="https://api.dicebear.com/7.x/adventurer-neutral/svg?seed=mail@ashallendesign.co.uk"
												/>
												<img
													className={styles.monthCalendarCellIcon}
													src="https://api.dicebear.com/7.x/adventurer-neutral/svg?seed=mail@ashallendesign.co.uk"
												/>
											</Flex>
										)
									);
								}}
								headerRender={() => null}
							/>
						</div>
					)}

					{type === 'year' && (
						<div className={styles.yearCalendarWrapper}>
							<Calendar
								cellRender={(a) => {
									if (a.date() === 10 || a.date() === 20) {
										return (
											<div className={styles.yearCalendarCell}>
												<div className={styles.yearCalendarDot}></div>
											</div>
										);
									}
									if (a.date() === 8 || a.date() === 8) {
										return (
											<div className={styles.yearCalendarCell}>
												<div className={styles.yearCalendarLine}></div>
											</div>
										);
									}
									if (a.date() === 12 || a.date() === 12) {
										return (
											<div className={styles.yearCalendarCell}>
												<div className={styles.yearCalendarLine}></div>
												<div className={styles.yearCalendarDot}></div>
											</div>
										);
									}
									return <div className={styles.yearCalendarCell}></div>;
								}}
								headerRender={() => (
									<Flex justify="center" className={styles.yearCalendarHeader}>
										{dayjs(date).format('MMMM')} {year}
									</Flex>
								)}
								value={dayjs(date)}
								fullscreen={false}
							/>
						</div>
					)}
				</Flex>
			</Content>
		</Page>
	);
};

export default Planner;
